// /frontend-react/src/App.js

import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import MedicalDashboard from './components/MedicalDashboard';
import AppointmentFlow from './components/AppointmentFlow';
import TransportStatus from './components/TransportStatus';
import HeaderBar from './components/HeaderBar';

// Mock data (remains the same)
const mockAppointmentData = { date: 'Dec 10', time: '10:00 AM', hasTransportBooked: false };

function App() {
    const [currentPage, setCurrentPage] = useState('dashboard'); 
    const [isEasyMode] = useState(true); 

    const handleNotificationClick = () => {
        setCurrentPage('appointment');
    };

    const renderPage = () => {
        // ... (renderPage logic remains the same - defined in your previous code block)
        if (currentPage === 'dashboard') {
            return (
                <Dashboard isEasyMode={isEasyMode} goToMedical={() => setCurrentPage('medical-dashboard')} />
            );
        }
        if (currentPage === 'medical-dashboard') {
             return (
                <MedicalDashboard isEasyMode={isEasyMode} goToPage={setCurrentPage} />
            );
        }
        if (currentPage === 'appointment') {
            return (
                <AppointmentFlow
                    isEasyMode={isEasyMode}
                    appointment={mockAppointmentData}
                    goToTransportStatus={() => setCurrentPage('transport')} 
                    goToMedicalDashboard={() => setCurrentPage('medical-dashboard')} 
                />
            );
        }
        if (currentPage === 'transport') {
            return (
                <TransportStatus
                    isEasyMode={isEasyMode}
                    goToAppointmentFlow={() => setCurrentPage('appointment')} 
                    goToMedicalDashboard={() => setCurrentPage('medical-dashboard')} 
                />
            );
        }
        if (currentPage === 'medicine') {
            return (
                <div style={{ padding: '0 20px 20px 20px', textAlign: 'center' }}>
                    <HeaderBar title="Medicine Reminders" onBackClick={() => setCurrentPage('medical-dashboard')} isEasyMode={isEasyMode} />
                    <h2 style={{fontSize: isEasyMode ? '48px' : '30px', marginTop: '20px'}}>💊 Medicine Reminders</h2>
                    <p style={{fontSize: isEasyMode ? '30px' : '16px'}}>Feature not built yet. Tap the arrow above to go back.</p>
                </div>
            );
        }
    };

    // Styles to hide the scrollbar while keeping scrolling active
    const scrollbarHiddenStyle = {
        // Hide scrollbar for Chrome, Safari and Opera
        '::-webkit-scrollbar': { display: 'none' },
        // Hide scrollbar for IE and Edge (though Edge supports WebKit prefixes now)
        'msOverflowStyle': 'none', 
        // Firefox (Requires using a separate stylesheet/CSS class, but we'll include the standard properties here)
        'scrollbarWidth': 'none',
    };

    return (
        // Outer container: Centers the frame on the desktop screen, prevents outer scroll
        <div style={{
            padding: '20px',
            backgroundColor: '#f0f0f0', 
            minHeight: '100vh', 
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center', 
        }}>
            
            {/* 📱 Phone Casing / Outer Frame */}
            <div 
                style={{
                    maxWidth: '400px', // Slightly smaller width
                    width: '100%',
                    height: '750px',  // Slightly reduced height
                    margin: '20px 0',
                    border: '15px solid #333', 
                    borderRadius: '40px', 
                    boxShadow: '0 10px 40px rgba(0,0,0,0.5)',
                    backgroundColor: '#000', 
                    position: 'relative',
                    flexShrink: 0,
                }}
            >
                {/* Mock Speaker/Notch (Visual Detail) */}
                <div style={{
                    position: 'absolute',
                    top: '5px',
                    left: '50%',
                    transform: 'translateX(-50%)',
                    width: '100px',
                    height: '8px',
                    backgroundColor: '#444',
                    borderRadius: '4px',
                    zIndex: 20
                }}></div>

                {/* Inner App Content Screen (This is the scrollable area with hidden scrollbar) */}
                <div 
                    style={{
                        height: '100%',
                        width: '100%',
                        backgroundColor: '#ffffff',
                        borderRadius: '25px', 
                        overflowY: 'auto', 
                        boxSizing: 'border-box',
                        // Applying the scrollbar hiding styles
                        ...scrollbarHiddenStyle,
                    }}
                    className={`App ${isEasyMode ? 'easy-mode-theme' : 'standard-theme'}`}
                >
                    {/* Mock Notification Banner (Positioning updated) */}
                    {currentPage === 'dashboard' && (
                        <div 
                            onClick={handleNotificationClick}
                            style={{ 
                                padding: '15px', 
                                backgroundColor: '#ffdddd', 
                                color: 'red',
                                textAlign: 'center',
                                cursor: 'pointer',
                                fontSize: isEasyMode ? '28px' : '16px',
                                fontWeight: 'bold',
                                borderBottom: '2px solid red',
                                position: 'sticky', 
                                top: 0,
                                zIndex: 10
                            }}
                        >
                            🚨 **NOTIFICATION: Appointment Soon! Tap Here!** 🚨
                        </div>
                    )}
                    
                    {renderPage()}
                </div>
            </div>
        </div>
    );
}

export default App;
